import numpy as np
from scipy import sparse
from baseline_registry import ROOT,REPO,ref,dump,sha

def main():
 start=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'producer.py');src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);q=p['q'];lo=p['lower'];hi=p['upper'];D=p['D'];E=p['E'];eq=np.isfinite(hi)&(hi==lo);ineq=~eq;records=[];checks=dict(original2208rows=A.shape[0]==2208,original72230coordinates=P.shape[0]==72230,no_physical_regularization=s['physical_regularization']==0.,all_original_inequalities_retained=s['all_original_inequalities_retained'],no_physical_update=s['actual_support_updates']==0,executed_at_least_one_pivot=s['pivots_executed']>0);prior=None
 for row in s['pivot_results']:
  c=np.load(REPO/row['output']['path']);x=np.r_[c['increment_mm'],c['tension_extension_mm']];y=c['physical_dual'];active=c['active'];basis=c['basis'];T=c['T'];yb=c['basis_dual'];ys=c['full_scaled_active_dual'];abrows=active[basis];z=c['scaled_solution'];sl=A@x-lo;g=P@x+q+A.T@y;scaled=sparse.diags(E[active])@A[active]@sparse.diags(D);rowerr=float(np.max(abs(scaled.toarray()-T@scaled[basis].toarray())));rhserr=float(np.max(abs((E[active]*lo[active]-T@(E[abrows]*lo[abrows]))/E[active])));metrics=dict(physical_primal_mm=max(float(np.max(np.maximum(-sl,0))),float(np.max(abs(sl[eq])))),physical_dual_N=float(np.max(abs(g))),physical_sign_defect_N=float(np.max(np.maximum(y[ineq],0))),physical_complementarity_Nmm=float(np.max(abs(sl[ineq]*y[ineq]))));qualified=all(v<1e-8 for v in metrics.values());v=c['cone_separator_basis'];w=T@v;eqdef=float(np.max(abs(w[~ineq[active]])));minineq=float(np.min(w[ineq[active]]));dot=float(yb@v);witness=row['conic_recovery_max_basis_residual']>1e-8 and eqdef<1e-8 and minineq>-1e-8 and dot>1e-8;release=active[ineq[active]&(w>1e-6)] if witness else np.array([],dtype=int);violated=np.flatnonzero(ineq&(sl<-1e-8));physical_linear=float(np.max(abs(P@x+q+A[abrows].T@(E[abrows]*yb))));active_linear=float(np.max(abs((A@x-lo)[active])));cone_error=float(np.max(abs(T.T@ys-yb)));yc=np.zeros(len(y));yc[active]=E[active]*ys
  local=dict(source_hash=sha(REPO/row['output']['path'])==row['output']['SHA256'],all_gauges_in_working_set=bool(np.all(np.isin(np.flatnonzero(eq),active))),active_basis_row_reconstruction=rowerr<1e-10,active_RHS_reconstruction=rhserr<1e-10,physical_metric_reproduced=max(abs(metrics[k]-row[k]) for k in metrics)<1e-10,all_original_duals_recovered=float(np.max(abs(y-yc)))<1e-10,physical_slack_reproduced=float(np.max(abs(sl-c['physical_slack_mm'])))<1e-12,physical_stationarity_reproduced=float(np.max(abs(g-c['physical_stationarity_N'])))<1e-10,cone_recovery_reproduced=abs(cone_error-row['conic_recovery_max_basis_residual'])<1e-10,witness_flag_matches=bool(witness)==row['cone_separator_verified'],witness_rows_reproduced=float(np.max(abs(w-c['cone_separator_rows'])))<1e-10,release_only_original_inequalities=release.tolist()==row['release_original_rows'],all_violated_original_rows=violated.tolist()==row['violated_original_rows'],qualification_matches=qualified==row['physical_KKT_qualified'])
  if witness:local['reversed_separator_rejected']=float(np.min(-w[ineq[active]]))<-1e-3 and -dot<0
  if prior is not None:
   prev,cprev=prior
   expected=np.setdiff1d(cprev['active'],np.array(prev['release_original_rows'],int)) if prev['release_original_rows'] else np.union1d(cprev['active'],np.array(prev['violated_original_rows'],int))
   local['physical_working_set_transition_reproduced']=bool(np.array_equal(expected,active))
  checks[f'pivot{row["pivot"]}']=all(local.values());records.append(dict(pivot=row['pivot'],checks={k:bool(vv) for k,vv in local.items()},metrics=metrics,unbounded_basis_stationarity_N=physical_linear,active_equality_mm=active_linear,conic_basis_residual=cone_error,cone_witness=bool(witness),witness_equality_defect=eqdef,witness_min_inequality=minineq,witness_dot_basis_dual=dot,wrong_sign_separator_minimum=float(np.min(-w[ineq[active]])),physical_KKT_qualified=qualified,maximum_scaled_row_error=rowerr));prior=(row,c)
 cad=ROOT/'cad/exports/primaryP1_seated22/summary.json';cd=json.loads(cad.read_text());checks['78actual_CAD_hashes']=len(cd['part_references'])==78 and all(sha(REPO/r['path'])==r['SHA256'] for r in cd['part_references'].values());result=dict(status='ACTUAL_P1_MATRIXFREE_PIVOT_INDEPENDENT_AUDIT_PASS' if all(checks.values()) else 'ACTUAL_P1_MATRIXFREE_PIVOT_INDEPENDENT_AUDIT_FAIL',candidate=ref(cad),source=ref(src),producer=ref(out/'producer.py'),checks={k:bool(v) for k,v in checks.items()},pivots=records,actual_support_updates=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-start,limitations=['Cone witness refers to computed equality-basis multiplier, not continuum impossibility. All original physical-row residuals are reported separately.','Audit PASS verifies transitions and rejection/qualification of linear diagnostic only. No nonlinear accepted equilibrium, attachedload/gamma, strength, energy or system gate PASS.']);dump(out/'summary.json',result);print(json.dumps(result));raise SystemExit(0 if all(checks.values()) else 2)
if __name__=='__main__':main()
